using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
[InitializeOnLoad]public static class Scene05VisibleProbe{
static double captureAt;
static Scene05VisibleProbe(){EditorApplication.delayCall+=Reopen;}
static void Reopen(){if(File.Exists("Temp/scene05-visible-verified.txt"))return;UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Project3D/Scenes/scene_05.unity");captureAt=EditorApplication.timeSinceStartup+3;EditorApplication.update+=Tick;}
static void Tick(){if(EditorApplication.timeSinceStartup<captureAt)return;EditorApplication.update-=Tick;Run();}
static void Run(){if(File.Exists("Temp/scene05-visible-verified.txt"))return;try{var lines=new System.Collections.Generic.List<string>();lines.Add("playing="+EditorApplication.isPlaying+" scene="+UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().path);foreach(var f in UnityEngine.Object.FindObjectsOfType<MeshFilter>(true).Where(f=>f.name.Contains("rowhouse"))){var r=f.GetComponent<MeshRenderer>();lines.Add(f.name+" active="+f.gameObject.activeInHierarchy+" enabled="+r.enabled+" forcedOff="+r.forceRenderingOff+" hide="+SceneVisibilityManager.instance.IsHidden(f.gameObject)+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" bounds="+r.bounds+" scale="+f.transform.lossyScale+" materials="+string.Join(",",r.sharedMaterials.Select(m=>m?m.name+":"+m.shader.name:"NULL")));lines.Add(f.transform.localToWorldMatrix.ToString());}File.WriteAllLines("Temp/scene05-visible-verified.txt",lines);var go=new GameObject("Wall preview camera");var c=go.AddComponent<Camera>();c.transform.position=new Vector3(0,1.5f,0);c.transform.rotation=Quaternion.LookRotation(new Vector3(0,0,-1));c.nearClipPlane=.02f;c.fieldOfView=90;var rt=new RenderTexture(1000,700,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(1000,700,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1000,700),0,0);t.Apply();File.WriteAllBytes("Previews/Scene05Homecoming/Walls_Verified.png",t.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}catch(Exception e){File.WriteAllText("Temp/scene05-visible-verified.txt",e.ToString());}}
}
